    components = defaultdict(list)
    for r in range(n):
        for c in range(m):
            if not visited[r][c]:
                color = grid[r][c]
                comp = []
                stack = [(r, c)]
                while stack:
                    br, bc = stack.pop()
                    if visited[br][bc]: continue
                    visited[br][bc] = True
                    comp.append((br, bc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
